import abc
from dataclasses import dataclass

import pandas as pd


@dataclass
class Signal:
    direction: str  # "BUY", "SELL", or "HOLD"
    price: float
    bar_index: int


class BaseStrategy(abc.ABC):
    @abc.abstractmethod
    def generate_signal(self, prev: pd.Series, curr: pd.Series) -> Signal:
        ...
